use crate::{FsRoute, FsRouteKind};

/// Marker written at the top of generated web-page `lambda.rs` files.
pub const GENERATED_PAGE_LAMBDA_MARKER: &str =
    "// @generated by ores-api-docs for a *-web-server.rs page; DO NOT EDIT.";

/// Provider hosts are deliberately outside api-docs. The generated source calls
/// a small, stable runtime facade supplied by the owning `*-lambdas` crate.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PageLambdaHost {
    Aws,
    Gcp,
}

impl PageLambdaHost {
    const fn feature(self) -> &'static str {
        match self {
            Self::Aws => "ores-page-lambda-aws",
            Self::Gcp => "ores-page-lambda-gcp",
        }
    }

    const fn runner(self) -> &'static str {
        match self {
            Self::Aws => "aws::run_page",
            Self::Gcp => "gcp::run_page",
        }
    }
}

/// Generate one provider-specific executable source file for a browser page.
///
/// This is intentionally a **web-page** projection. It never imports RPC
/// dispatch code, never generates `rpc.rs`, and never turns the page into an
/// api-docs operation. `ores-stack` owns when/where this file is materialized.
pub fn page_lambda_glue(route: &FsRoute, host: PageLambdaHost) -> Result<String, String> {
    if route.kind != FsRouteKind::Page {
        return Err("page_lambda_glue accepts only src/pages/**/page.rs routes".to_owned());
    }

    let canonical_path = route.canonical_path();
    let axum_paths = route.axum_paths();
    let feature = host.feature();
    let runner = host.runner();

    let mut out = String::new();
    out.push_str(GENERATED_PAGE_LAMBDA_MARKER);
    out.push('\n');
    out.push_str("// WEB SERVER PAGE LAMBDA ONLY — not an API-server RPC adapter.\n\n");
    out.push_str("#[path = \"page.rs\"]\nmod __ores_page;\n\n");
    out.push_str(&format!(
        "pub const ORES_PAGE_SOURCE: &str = {:?};\npub const ORES_PAGE_ROUTE: &str = {:?};\npub const ORES_PAGE_AXUM_PATHS: &[&str] = &[{}];\n\n",
        route.source,
        canonical_path,
        axum_paths
            .iter()
            .map(|path| format!("{path:?}"))
            .collect::<Vec<_>>()
            .join(", ")
    ));
    out.push_str(
        "async fn __ores_handle_page(\n    request: ::ores_page_lambda_runtime::PageHttpRequest,\n) -> Result<::ores_page_lambda_runtime::PageHttpResponse, ::ores_page_lambda_runtime::RuntimeError> {\n    ::ores_page_lambda_runtime::invoke_page(\n        request,\n        ORES_PAGE_ROUTE,\n        ORES_PAGE_AXUM_PATHS,\n        |ctx| __ores_page::__ores_page_boxed(ctx),\n    ).await\n}\n\n",
    );
    out.push_str(&format!(
        "#[cfg(feature = {feature:?})]\n#[tokio::main]\nasync fn main() -> Result<(), ::ores_page_lambda_runtime::RuntimeError> {{\n    ::ores_page_lambda_runtime::{runner}(__ores_handle_page).await\n}}\n\n"
    ));
    out.push_str(&format!(
        "#[cfg(not(feature = {feature:?}))]\ncompile_error!(\"generated page lambda must be built with feature {feature}\");\n"
    ));
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generates_web_only_aws_entrypoint() {
        let route = FsRoute::page("src/pages/users/[id]/page.rs").expect("page route");
        let source = page_lambda_glue(&route, PageLambdaHost::Aws).expect("lambda source");
        assert!(source.starts_with(GENERATED_PAGE_LAMBDA_MARKER));
        assert!(source.contains("WEB SERVER PAGE LAMBDA ONLY"));
        assert!(source.contains("ORES_PAGE_ROUTE: &str = \"/users/{id}\""));
        assert!(source.contains("ores_page_lambda_runtime::aws::run_page"));
        assert!(!source.contains("rpc.rs"));
        assert!(!source.contains("RpcV1"));
    }

    #[test]
    fn generates_gcp_host_without_changing_page_contract() {
        let route = FsRoute::page("src/pages/docs/[[...slug]]/page.rs").expect("page route");
        let source = page_lambda_glue(&route, PageLambdaHost::Gcp).expect("lambda source");
        assert!(source.contains("ores-page-lambda-gcp"));
        assert!(source.contains("ores_page_lambda_runtime::gcp::run_page"));
        assert!(source.contains("\"/docs\", \"/docs/{*slug}\""));
    }

    #[test]
    fn refuses_api_routes() {
        let route = FsRoute::api_handler("src/routes/v1/health/route.rs").expect("api route");
        let error = page_lambda_glue(&route, PageLambdaHost::Aws).expect_err("must refuse api");
        assert!(error.contains("only src/pages/**/page.rs"));
    }
}
